 1px solid #e2e8f0; border-radius: 12px; background: #fff; color: #64748b; padding: 4px 8px; font-size: 8px; }.filter-pill b { font-family: var(--mono); font-size: 7px; }.filter-pill.selected { background: #f1f5f9; color: #334155; border-color: #cbd5e1; }.filter-pill[data-filter="TRIP"] { color: #dc2626; }.filter-pill[data-filter="ALARM"] { color: #d97706; }.metric-select { margin-left: auto; color: #94a3b8; font-size: 8px; }.metric-select select { margin-left: 5px; border: 1px solid #e2e8f0; border-radius: 4px; background: #fff; color: #475569; padding: 4px 6px; font-size: 8px; }.trcc-legend { display: flex; gap: 8px; color: #64748b; font-size: 8px; }.trcc-legend span { display: flex; align-items: center; gap: 3px; }.trcc-legend i { width: 5px; height: 5px; border-radius: 50%; }.trcc-split { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 14px; align-items: start; }.field-list { max-height: calc(100vh - 150px); overflow-y: auto; padding: 8px 0 20px; }.field-section { margin-bottom: 17px; }.field-section h2 { margin: 0 0 7px 2px; color: #64748b; font-size: 8px; font-weight: 600; }.field-section h2 span { color: #94a3b8; font-weight: 400; }.field-grid { display: grid; grid-template-columns: repeat(12, minmax(39px, 1fr)); gap: 4px; }.unit-tile { min-height: 56px; padding: 7px 3px; border: 1px solid #e2e8f0; border-radius: 6px; background: #f8fafc; color: #94a3b8; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; cursor: pointer; }.unit-tile:hover, .unit-tile.selected { border-color: #64748b; box-shadow: 0 0 0 1px #64748b; }.unit-tile strong { font: 600 9px var(--mono); color: #64748b; }.unit-tile small { font: 7px var(--mono); color: #94a3b8; }.unit-dot { width: 5px; height: 5px; border-radius: 50%; background: #16a34a; }.unit-tile.alarm { background: #fff7ed; border-color: #fed7aa; }.unit-tile.alarm .unit-dot { background: #f59e0b; }.unit-tile.trip { background: #fef2f2; border-color: #fecaca; }.unit-tile.trip .unit-dot { background: #ef4444; }.unit-tile.off { background: #f1f5f9; }.unit-tile.off .unit-dot { background: #94a3b8; }.inspector { min-height: calc(100vh - 150px); padding: 13px; background: #fff; border-left: 1px solid #e2e8f0; box-shadow: -2px 0 8px rgba(15, 23, 42, .03); }.inspector-head { display: flex; align-items: flex-start; justify-content: space-between; border-bottom: 1px solid #f1f5f9; padding-bottom: 12px; }.inspector-head h2 { margin: 0 0 8px; font-size: 13px; }.inspector-pills { display: flex; gap: 5px; }.status-pill { padding: 4px 7px; border-radius: 10px; background: #f1f5f9; color: #64748b; font-size: 8px; font-weight: 600; }.status-pill.ok { background: #dcfce7; color: #15803d; }.status-pill.alarm { background: #ffedd5; color: #c2410c; }.status-pill.trip { background: #fee2e2; color: #dc2626; }.trends-button { border: 1px solid #e2e8f0; border-radius: 4px; background: #fff; color: #64748b; padding: 5px 7px; font-size: 8px; }.inspector h3 { margin: 13px 0 7px; color: #64748b; font-size: 8px; letter-spacing: .4px; }.electrical-grid, .fault-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 3px; }.metric-card { min-height: 36px; padding: 6px 7px; background: #f8fafc; border: 1px solid #eef2f6; border-radius: 3px; }.metric-card span { display: block; color: #94a3b8; font-size: 7px; }.metric-card strong { display: block; margin-top: 3px; color: #475569; font: 600 9px var(--mono); }.fault-pill { display: flex; justify-content: space-between; padding: 5px 7px; background: #f8fafc; border: 1px solid #eef2f6; border-radius: 3px; color: #64748b; font: 7px var(--mono); }.fault-pill b { color: #94a3b8; font-size: 6px; }.fault-pill.active { color: #dc2626; border-color: #fecaca; background: #fef2f2; }.fault-pill.active b { color: #dc2626; }
