   }

   function mount() {
     if (unsubscribe) unsubscribe();
     render(window.EpmsStore.getState());
     unsubscribe = window.EpmsStore.subscribe((state) => {
       if (document.querySelector(".alarms-view")) render(state);
     });
   }

   function unmount() {
     if (unsubscribe) unsubscribe();
     unsubscribe = null;
   }

   window.EpmsAlarms = { mount, unmount };
 }(window));

